#!/usr/bin/env bash
# Gate `executable-text-eol-pinned` for [R:pin-eol-for-executable-text], generated by relearn from the rule file.
# Edit the rule, never this script: `relearn verify` reports a hand edit.
# Engine: eol-attribute. Records: path, first_line, text, eol, tab-separated.
#   bash executable-text-eol-pinned.sh <repository root>   0 clean, 1 finding, 2 could not check
#   bash executable-text-eol-pinned.sh --judge < records   0 clean, 1 hit (the fixture runner)
# A `warn` gate prints its finding and exits 0.
set -uo pipefail
export LC_ALL=C

name='executable-text-eol-pinned'
tag='R:pin-eol-for-executable-text'
message='A tracked file whose first line is a shebang has no pinned line ending, so a checkout may rewrite it to CRLF and the interpreter is then not found. Pin it at rest in .gitattributes (<glob> text eol=lf), rather than teaching anything downstream to forgive the bytes.'
export RL_FILES='((^|/).*$)'
export RL_EXCLUDE=''
export RL_ALWAYS=''

# Judge: 4 field(s) per record on stdin. 0 clean, 1 hit, 3 unreadable.
judge() {
  awk '
BEGIN {
  FS = "\t"
  files = ENVIRON["RL_FILES"]
  excl = ENVIRON["RL_EXCLUDE"]
  hits = 0
  bad = 0
  always = ENVIRON["RL_ALWAYS"]
}
$0 == "" { next }
NF != 4 { bad = 1; next }
$1 !~ files { next }
excl != "" && $1 ~ excl { next }
{
  shebang = ($2 ~ /^#!/)
  needs = shebang || (always != "" && $1 ~ always)
  pinned = ($4 == "lf") || ($3 == "unset") || ($4 == "crlf" && !shebang)
  if (needs && !pinned) { print $1; hits++ }
}
END { if (bad) exit 3; exit (hits > 0) }
'
}

# Collect: every tracked path, its first line (tabs and CR removed), and
# `git check-attr` for text and eol. The attributes are the repository's own:
# this machine's system and global config are switched off, and the per-user
# attributes file is pointed at an empty one, because a pin that lives only on
# one machine is not a pin (git 2.32 or later; `.git/info/attributes`, per
# clone, is still read).
collect() {
  (
    cd "$1" || exit 1
    : > "$work/empty" || exit 1
    export GIT_CONFIG_NOSYSTEM=1 GIT_ATTR_NOSYSTEM=1 GIT_CONFIG_GLOBAL="$work/empty"
    git ls-files -z > "$work/paths" || exit 1
    git -c core.attributesFile="$work/empty" check-attr -z --stdin text eol \
      < "$work/paths" > "$work/attrs" || exit 1
    : > "$work/first"
    if [ -s "$work/paths" ]; then
      xargs -0 awk 'FNR == 1 { l = $0; gsub(/[\t\r]/, "", l); print FILENAME "\t" l; nextfile }' \
        < "$work/paths" > "$work/first" 2>/dev/null
    fi
    tr '\0' '\n' < "$work/paths" > "$work/paths.nl"
    tr '\0' '\n' < "$work/attrs" > "$work/attrs.nl"
    awk '
BEGIN { FS = "\t" }
FILENAME == ARGV[1] { first[$1] = $2; next }
FILENAME == ARGV[2] { n++; if (n % 3 == 1) p = $0; else if (n % 3 == 2) a = $0; else v[p, a] = $0; next }
{ print $0 "\t" first[$0] "\t" v[$0, "text"] "\t" v[$0, "eol"] }
' "$work/first" "$work/attrs.nl" "$work/paths.nl"
  )
}

if [ "${1:-}" = "--judge" ]; then
  judge
  exit $?
fi

disarmed() {
  printf '[%s] %s: DISARMED (exit 2, not a pass): %s\n' "$tag" "$name" "$1" >&2
  exit 2
}
root="${1:-.}"
command -v git >/dev/null 2>&1 || disarmed "git is not on PATH"
git -C "$root" rev-parse --is-inside-work-tree >/dev/null 2>&1 \
  || disarmed "$root is not a git checkout"
work="$(mktemp -d)" || disarmed "no scratch directory"
trap 'rm -rf "$work"' EXIT
collect "$root" > "$work/records" || disarmed "the collect stage failed"
judge < "$work/records" > "$work/findings"
case $? in
  0) exit 0 ;;
  1) ;;
  *) disarmed "the judge could not read a record" ;;
esac
count="$(wc -l < "$work/findings" | tr -d ' ')"
printf '[%s] %s: BLOCKED. %s\n' "$tag" "$name" "$message"
printf '%s finding(s) in %s:\n' "$count" "$root"
sed 's/^/  /' "$work/findings"
exit 1

